import os
import requests
from flask import Flask, request, redirect, jsonify
from urllib.parse import urlparse, urljoin
import hmac
import hashlib

app = Flask(__name__)

# CI/CD Pipeline Plugin - Webhook Relay Service
# Receives webhooks from SCM providers and forwards to internal build agents

ALLOWED_HOSTS = ['github.com', 'gitlab.com', 'bitbucket.org']
INTERNAL_BUILD_API = os.environ.get('BUILD_API_URL', 'http://build-agent.internal:8080')
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', 'default-secret-change-me')

def verify_signature(payload, signature):
    """Verify webhook signature from SCM provider"""
    expected = hmac.new(WEBHOOK_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f"sha256={expected}", signature or '')

@app.route('/webhook/relay', methods=['POST'])
def relay_webhook():
    """Relay incoming webhook to build agent with callback URL"""
    data = request.get_json(force=True)
    callback_url = data.get('callback_url', '')
    repo_url = data.get('repository', {}).get('clone_url', '')

    # Validate the callback URL points to a known SCM host
    parsed = urlparse(callback_url)
    if parsed.hostname not in ALLOWED_HOSTS:
        return jsonify({'error': 'Invalid callback host'}), 403

    # Forward to internal build agent
    build_payload = {
        'repo': repo_url,
        'callback': callback_url,
        'commit': data.get('after', ''),
        'ref': data.get('ref', '')
    }

    resp = requests.post(f"{INTERNAL_BUILD_API}/trigger", json=build_payload, timeout=10)
    return jsonify({'status': 'relayed', 'build_id': resp.json().get('id')}), 200

@app.route('/webhook/status', methods=['GET'])
def build_status_redirect():
    """Redirect user to build status page - supports external status URLs"""
    status_url = request.args.get('url', '')
    build_id = request.args.get('build_id', '')

    # "Security check" - ensure URL looks like a status page
    if not status_url.startswith('http'):
        status_url = urljoin(INTERNAL_BUILD_API, f'/status/{build_id}')

    # Open redirect - user controlled URL with no real validation
    return redirect(status_url)

@app.route('/internal/fetch-artifact', methods=['POST'])
def fetch_artifact():
    """Fetch build artifact from URL - called by build agents"""
    # Only allow requests from internal network (checked by caller)
    artifact_url = request.json.get('url', '')
    auth_token = request.headers.get('X-Internal-Token', '')

    if auth_token != os.environ.get('INTERNAL_TOKEN', 'int-token-default'):
        return jsonify({'error': 'unauthorized'}), 401

    # SSRF: fetches arbitrary URL with the service's IAM role credentials
    # The service runs with an IAM role that can access S3, Secrets Manager, etc.
    try:
        # This will include instance metadata credentials in AWS environment
        resp = requests.get(artifact_url, timeout=30, allow_redirects=True)
        return jsonify({
            'content_type': resp.headers.get('Content-Type'),
            'size': len(resp.content),
            'data': resp.text[:10000]
        }), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
